        "text": "허연의 시에서 슬픔과 고독, 그로 인한 통증은 필연적이다. 화자에게 삶이란 마치 죽음의 바탕과도 같아서, 약간의 장력으로도 휘말려 들어가는 넝마처럼 어둠에 근접해 있다. 사랑은 버림으로, 솟구침은 가라앉음으로, 욕망은 절망으로 귀결된다. 거기엔 마땅한 계기가 없다. 눈뜬 직후 육체를 파고드는 세상의 빛과 형상이 주는 피로감이며, 그 느낌은 막연한 가능성에 존재를 매달리게 해 삶을 짓누른다. 그리고 이것은 허연이라는 한 개인의 숙명이자 시인으로서 그가 갖춘 생래적인 감각이다. 그리하여 허연 시의 화자는 “나쁜 계절과 나빠질 계절”만을 겪어왔으나 오로지 자신만이 버틸 수 있는 구역을 만들어낸다. “슬픔에도 기술이 있”으므로, “통증에 시달리며 이 구역의 계절을 만든다”. 오로지 살기 위한 이러한 선택은 세상과 통하는 새로운 길을 터, 성(聖)과 속(俗)이 교차하는 영혼의 집을 짓는다. “성당”(「계절감」)은 시가 초개인적인 힘을 드러내는 문학적 지대이면서, 방황하는 이들을 붙들고 껴안는 장소다. 그곳에서 화자는 늙은 아버지, 죽은 애인, 한 시절의 길고양이 등 저마다의 사연으로 “가득 찼던 것들”(「시월의 시」)과 만나고 이별하며 “같아지지 않되/녹아드는 일”[「쓸데없는 화살-시작법(詩作法)」]을 체험한다. 그렇게 “생은 잠시 초라해졌다가 다시 화색이 돌기도 한다”(「가여운 거리」). 독자는 생(生)과 사(死)의 기묘한 동일시 속에서, 죽음을 물려받았으되 각각의 모습으로 다시 태어나는 인간사를 읽으며 깊이 매혹된다."
