        "recommender": "본점 현지",
        "text": "‘자축인묘진사오미신유술해’ 12마리 동물들의 생일날 재미있는 에피소드가 담겨있는 책이다.\n생일은 왜 축하받아야 하는 걸까? 이 그림책은 생일은 왜 축하받아야 하는지 12마리 동물들의 이야기를\n통해 우리 모두가 소중하고 특별한 존재임을 알려준다. 어쩌면 생일날 생일선물을 하는 것, 축하하는 것을\n받은만큼 돌려줘야한다는 의무감에 할 때도 있었다. 생일에 큰 의미를 가진 사람이 아니었지만, 이 책을\n읽고 나니 내 생일뿐만 아니라 사랑하는 사람의 생일에 더 진심을 다 해 축하해 주고 싶은 마음이 들었다.\n재미있는 이야기와 눈을 뗄 수 없을 만큼 알록달록한 색감과 풍부한 그림체로 눈까지 즐거운 생일 이야기를 만나볼 수 있다. 십이간지 동물들도 배울 수 있는 재미, 교훈, 지식 빠짐없는 그림책이다."
