        "text": "밥은 먹고 다니냐?' 는 공부 잘했던 친구의 40여년만의 뜬금없는 전화에 이 책을 쓰게된\n공부 못했던 저자의 죄충우돌, 기상천외, 단짠단짠 성장기.\n웃으면서 읽었고, 가슴이 짠해지기도 했다. 그렇다.\n우리는 공부 잘하고 싶고 돈도 많이 벌고 싶고 여우같고 토끼같고 늑대같은 이들과 단란하게 살고 싶었다,\n버뜨 그게 다 이루어지는 삶이 어디 있겠나?\n그래도 한발짝한발짝 달고 쓰고 싱그럽고 비루하고 또 아름다운 삶을 열심히 만들어가는게\n우리들 모습이 아닐까?"
