        "recommender": "문재인",
        "text": "유쾌한 책을 한 권 추천합니다. <공부 못했던 그 친구는 어떻게 살고 있을까>. ‘공부 못했던 그 친구’는 저자 자신입니다. 구로산바몬드란 필명으로 가렸지만 저자는 양산에 있는 중학교 교감 선생님입니다. 공부 못했던 저자가 어렵게 어렵게 학창생활을 헤쳐나가 교사가 되고, 아이들을 가르치게 된 삶의 에피소드들을 담았습니다.\n‘어렵게 어렵게’는 ‘공부 못해서 어렵게’와 ‘가난해서 어렵게’가 더해졌습니다. 그래도 유쾌합니다. 대학시절 생활비와 학비를 벌기 위해 기를 쓴 알바 생활과 허기진 배를 채우기 위한 처절한 노력들까지도 유머 있는 글솜씨 덕분에 유쾌하게 읽을 수 있습니다. 나는 책을 읽으며 머리말부터 시작해서 몇 번이나 배꼽을 잡았고, 웃음을 참을 수가 없었습니다.\n이 책은 저자의 이야기이지만, 같은 시대를 힘들게 살아온 세상사람들에게 ‘고생했어! 그래도 우리 잘해 왔어!’ 다독여주고 위로하는 책입니다. 또 힘들게 살아가야할 젊은 세대에게 보내는 위로입니다.\n세상의 모든 공부 못하는 사람들에게 이 책을 추천합니다. 공부 잘하고 잘난 사람들에게도 세상과 더 공감하기를 바라며 추천하고 싶습니다."
