        "period": "재임 전 · 2016년 2월 4일",
        "recommender": "문재인",
        "text": "- 오현스님의 한글 선시(禪詩)를 한편 소개합니다. 그냥 좋아서, 보여드리고 싶어서 올립니다. 시의 형식은 시조입니다. 시조의 격조와 선시(禪詩)의 심오함이 잘 어우러졌습니다.\n<아득한 성자>\n하루라는 오늘\n오늘이라는 이 하루에\n뜨는 해도 다 보고\n지는 해도 다 보았다고\n더 이상 더 볼 것 없다고\n알 까고 죽는 하루살이 떼\n죽을 때가 지났는데도\n나는 살아 있지만\n그 어느 날 그 하루도 산 것 같지 않고 보면\n천년을 산다고 해도\n성자는\n아득한 하루살이 떼\n- 오현스님의 한글 선시(禪詩)를 한편 더 올립니다.\n한글 선시가 이렇게 기막힌 줄을 오현스님 시를 보고 처음 알았습니다.\n선시라면 옛 조사나 도 높은 스님들의 아리송한 한시(漢詩)만 생각했었습니다.\n이 시도 시조입니다.\n<인천만 낙조>\n그날 저녁은 유별나게 물이 붉다붉다 싶더니만\n밀물 때나 설물 때나 파도 위에 떠 살던\n그 늙은 어부가 그만 다음 날은 보이지 않데.\n- 오현스님의 한글 선시 가운데 제가 가장 좋아하는 시입니다.\n사실 이 시를 보여드리고 싶어서 먼저 시 두편을 올린 것입니다.\n많은 것을 생각하게 합니다.\n한글 선시의 깊은 맛과 오현스님의 도의 경지를 보여주는 작품입니다."
