        "text": "책도 읽지 않고 무위의 시간을 보낸다는 것이 마음대로 되지 않았습니다.\n휴가 중 읽은 <명견만리>는 누구에게나 읽어보기를 권하고 싶은 책 입니다. 세 권이지만 쉽고 재밌습니다.\n사회 변화의 속도가 무서울 정도로 빠르고 겪어보지 않은 세상이 밀려오고 있는 지금, 명견만리(明見萬里)할 수 있다면 얼마나 좋겠습니까?\n개인도 국가도 만 리까지는 아니어도 적어도 10년, 20년, 30년은 내다보면서 세상의 변화를 대비해야 할 때입니다.\n앞으로 다가올 세상이 지금까지와 다르다면 정치도 정책도 그러해야 할 것입니다.\n우리가 당면하고 있는 미래의 모습에 대해 공감하고 그 미래를 맞이하기 위해 무엇을 해야할 것인가에 대해 공감하기 위해 일독을 권합니다."
