        "text": "최초 유전물질에서 호모 사피엔스까지 지구 생명의 역사\n이 책은 지구 생명이 출발한 태초부터 이야기를 시작한다. 46억 년 전 우주를 떠돌던 성운이 뭉쳐져 지구가 만들어졌다. 그로부터 8억 년쯤 뒤에 물이 있는 환경에서 지구 최초 생명체가 나타났다. 이 생명체는 자기를 복제하는 능력을 가졌는데, 점점 조직화되는 과정을 거치며 세포들을 만들어 냈다. 세포들이 시간이 지나면서 각자의 기능을 분화시키며 다세포 생물이 탄생했다.\n긴 시간 물속에 있던 생물들 중 일부가 뭍으로 올라오면서 육지 동물이 생겼다. 육지 동물 중 누구는 파충류가 되고 누구는 조류가 되고 누구는 포유류가 되었다. 포유류 중 일부는 영장류가 되었다. 영장류가 여러 갈래로 나뉘어 진화하다가 지금으로부터 약 30만 년 전에 하나의 가지 끝에서 인간 종, 호모 사피엔스가 탄생했다. 지구 생명의 역사는 결국 태초에 등장한 최초 생명체, 그 유전물질의 일대기다. 인간은 어쩌면 그 유전물질에 이용당하고 있는 존재에 불과할지 모른다."
