        "text": "우리에게 스누피로 많이 알려진 만화 <피너츠>로 20세기 미국의 최고 만화가로 평가받는 찰스 슐츠는 1968년 마틴 루서 킹 목사의 암살 직후 독자로부터 한 통의 편지를 받습니다. 백인 일색의 <피너츠> 만화에 흑인 아이 캐릭터를 넣어주면 아이들이 인종에 대한 편견 없는 태도를 만드는 데 도움이 될 것 같다는 부탁이었습니다. 흑인에 대한 미국사회의 편견과 차별이 여전히 극심하여 흑인들의 저항운동이 분출되던 시기였습니다. 슐츠는 고심 끝에 이 제안을 받아들여 첫 흑인 아이 캐릭터를 등장시키고, 이 캐릭터가 등장하는 장면과 대사를 치밀하게 구성해서 당시 인종에 관해 논란되던 문제들을 다루면서도 독자들에게서 반발심이 아닌 공감을 이끌어냈습니다. 이 책은 인종차별뿐 아니라 교육 양극화로 인한 기회의 배제, 여성복 주머니에 담긴 차별, 여성들의 스포츠 진입 장벽, 장애인 권리 운동, 문화적 다양성의 가치 등 뿌리 깊고 오래된 편견과 차별을 다루면서, 제도화되고 관습화된 차별에 순응하기를 거부한 사람들의 이야기를 통해 세상이 이렇게 진보하고 있다는 희망을 보여줍니다.\n이 책의 이야기는 미국의 이야기이지만 바로 우리 자신의 이야기이기도 합니다. 편견과 차별 문제에 있어서 한국사회는 민주화 이후 많은 진전을 이뤘지만 아직도 OECD 국가들 가운데 최하위권일 만큼 낙후되어 있습니다. 민주주의를 퇴행시킨 정권들이 분열과 증오를 증폭시켜왔기 때문입니다. 이제 우리는 또다시 분열과 차별과 증오냐 통합과 포용과 화합이냐로 갈리는 역사의 갈림길에 서있습니다. 그 길목에서 읽어볼 만한 책으로 추천합니다."
