        "text": "‘소노 디스포니빌레’는 ‘나는 갈 것이다’ 또는 ‘나는 갈 준비가 되어 있다’는 이탈리아 말입니다. 얼마 전 선종하신 프란치스코 교황이 북한 방문 의사를 천명하면서 하셨던 말입니다. 저자는 그의 방북이 추진되던 때 주교황청 한국대사로 근무했습니다. 그 전에는 기자 출신으로 노무현 정부에서 홍보수석을 지냈습니다. 이 책은 저자가 현지에서 겪은 바티칸 3년의 기록이며, 우리 외교사의 한 페이지입니다. 교황의 방북을 위해 교황청과 남북한 정부 사이에 어떤 일이 있었으며 어디까지 진척됐었는지, 왜 좌절됐고 앞으로의 가능성은 어떠한지, 기자가 취재수첩으로 작성한 기사처럼 생생하고 현장감이 있습니다. 나 자신이 관여했던 일이지만, 나도 몰랐던 이면의 일들이 많아서 무척 흥미진진하게 읽었습니다. 몰입감 있게 단숨에 읽히는 책입니다.\n당시 교황의 방북은 북미간의 하노이 회담이 성공을 거두었다면 성사될 가능성이 매우 높았습니다. 비록 하노이 노딜과 뒤이은 코로나 대유행으로 좌절됐지만, 여건이 되면 다시 추진될 수 있는 미완의 프로젝트입니다. 트럼프 대통령은 때가 되면 다시 북한과의 대화에 나설 것이며, 그 과정에서 평양 방문이 전격적으로 이뤄질 가능성이 높습니다. 그럴 경우 교황의 방북도 지난번처럼 교황청과 남북한 당국의 의지만 보인다면 실현 가능한 일이 될 것입니다. 마침 카톨릭 세계청년대회가 2027년 8월 서울에서 열릴 예정입니다. 역대 교황이 관례적으로 참석해왔던 행사입니다. 새정부는 그 기회를 잘 활용할 필요가 있습니다. 비록 프란치스코 교황은 선종하셨지만, 새 교황의 방한이 그때 이뤄진다면 그 기회에 방북까지도 모색해 볼만 합니다. 주교황청 한국대사관은 외교관 3명에 일반직원이 몇 명밖에 되지 않는 미니 대사관이지만, 새정부가 교황청을 외교 정책의 전략적 거점으로 활용하기 바랍니다.\n이 책이 나온 지 일주일 만에 프란치스코 교황의 선종이란 안타까운 소식이 있었습니다. 그의 한국에 대한 각별한 애정과 방북 의지가 후임 교황에게 이어지기를 기대하며, 다시 한번 프란치스코 교황님의 영면을 기원합니다."
