        "text": "음모론에 사로잡힌 한국 사회. 입맛대로 취사된 통계가 음모론의 근거가 됩니다. 정치적 입장에 따라 진실이 갈립니다. 진실이 뒤집히고 왜곡되어 뭐가 옳은지 알 수 없게 만듭니다. 하지만 객관적 진실은 결국 데이터가 축적된 통계 숫자 속에 있습니다. 우리가 맥락을 이해하고 제대로 읽기만 한다면, 정치적 해석을 뚫고 진실을 보여주는 것은 통계 숫자입니다. 일시적인 통계가 아니라 장기간 통계의 흐름을 살피고, 세계 각국의 통계와 비교해 보는 것도 필요한 일입니다.\n코로나19 대유행 시기에 정부의 방역대책은 많은 반발에 부딪혔고, 백신접종은 음모론에 시달렸습니다. 하지만 이제 와서 세계 각국의 평균 수명 통계를 들여다보면, 그 기간 동안 일본을 포함해서 세계 중요국의 평균 수명이 모두 줄어든 반면, 유독 한국은 평균 수명이 되레 늘었습니다. 한국도 평균 수명이 줄어든 해가 있었는데, 그것은 사회적 거리두기가 종료된 2022년이었습니다. 이 책에서 다루진 않았지만, 경제에 있어서도 한국은 위기에 강한 면모를 보이면서 기적 같은 성장을 이루었습니다. 코로나가 한창이었던 2021년 한국의 1인당 국민소득은 3만 7,898불로 사상 최고치를 기록하며 일본을 추월했고, G7 국가에 버금가는 위상을 갖게 됐습니다. 현 정부 들어 국민소득은 그때보다 오히려 크게 줄었습니다. 결국 객관적 통계 숫자가 확인해 주는 진실은, 한국이 코로나 기간 동안 국민 보건과 경제 성장 두 마리 토끼를 모두 잡는 매우 유능하고 성공적인 대응을 해냈다는 사실입니다.\n이 책은 한국 사회를 제대로 이해하면서 어디로 가야 하는지 가늠할 수 있게 해 주는 다양한 통계들을 보여줍니다. 이 같은 통계 숫자 바로 읽기가 더 활발해지고 더 확장되어 가기를 바랍니다. 자살률, 사고사와 산재 사망자 같은 통계들을 살펴보면, 한국 사회가 과연 더 안전하고 따뜻한 사회로 가고 있는지 확인할 수 있습니다. 민주주의 지수, 언론자유 지수, 성평등 지수, 국가청렴도 지수 같은 통계들을 살펴보면, 한국 사회가 바람직한 방향으로 발전해 가고 있는 것인지 확인할 수 있을 것입니다."
