        "text": "모처럼 소설책을 추천합니다. <저주토끼>로 부커상과 전미도서상 최종후보에 올랐던 정보라 작가의 자전적 SF소설입니다. 진지하면서도 무척 유쾌하고 재미있습니다. 대담한 상상력과 유머 있는 글솜씨가 주는 재미입니다. 소설 제목이 문어, 대게, 상어, 개복치, 해파리, 고래인 6편의 연작단편소설이 담겨있습니다. 작가가 대부분 실화라고 밝힌 자전적인 이야기를 근간으로 하면서 소설 제목의 해양생물들을 외계생명체로 설정하여 현실세계와 SF세계를 넘나드는 구성이 경이롭고 환상적입니다.\n시간강사와 비정규직 노동자, 정리해고, 장애인의 이동권, 기후위기, 핵폐수 방류로 인한 해양오염 등 묵직한 사회문제들에 대한 작가의 치열한 비판의식과 저항의식이 소설마다 담겨있습니다. 하지만 읽기에 무겁지 않고, 재미와 공감을 함께 느낄 수 있습니다. 진지한 주제를 재미있게 전달해서 독자들의 공감을 얻고자한 작가의 의도가 멋지게 성공을 거두었습니다.\n위기에 맞설 수 있는 힘은 역시 사랑입니다. 대학시간강사로 비정규교수노조원이 되어 천막농성에 참여했던 주인공이 농성을 이끈 노조위원장과 부부가 되고, 함께 연대투쟁에 참여하면서 또 함께 외계생물체를 만나면서 보여주는 동지적인 신뢰와 사랑에 안도감을 느낍니다. 두 사람이 외롭지 않으며, 싸움에서 이기지 못하더라도 결코 꺾이지 않을 것이라는 안도감입니다. 가족들을 사랑하면서 왕성한 작품발표와 강연, 집회참가 등으로 사회운동에도 열심히 참여하고 있는 정보라 작가의 활동에 응원을 보냅니다."
