        "text": "이 책은 저자가 ‘집현네트워크’입니다. 집현네트워크는 세계적인 국내과학자 21인이 급변하는 과학기술과 기후위기의 시대에 집단지혜를 모으고 유통하기 위해 설립한 전문가단체 사단법인입니다.\n지구온난화로 인한 기후위기는 지금 시기 인류가 글로벌 차원에서 직면하고 있는 최대의 과제입니다. 우리는 올 여름 사상 초유의 폭우와 폭염으로 지구온난화로 인한 기후위기가 갈수록 심각해지고 있으며 변화의 속도가 대단히 빠르다는 사실을 절감하고 있습니다. 우리가 코로나19의 대유행으로 겪었던 신종감염병의 위기도 기후변화로부터 파생되는 위기입니다.\n그런데도 아직도 기후위기는 사기라거나 과장됐다거나 강 건너 불처럼 여기는 사람들이 많습니다. 문제는 이런 사람들이 기후정책을 결정하고 있다는 사실입니다. 문제를 알면서도 단기적인 경제실적을 올리는데 우선순위를 두다보니, 폭탄을 다음 정부로 떠넘기는 행태도 계속되고 있습니다.\n이제는 국민들이 제대로 알고 비판적인 사고를 해야할 때입니다. 이에 지구과학과 생명과학을 아우르는 집협네트워크의 분야별 전문가 40여명이 문제의 진단과 해법을 한 권의 책에 담았습니다. 해외의 최신 연구와 우리나라에 맞춤한 기후과학 지식을 모아서 펴낸 최초이자 유일한 ‘우리 기후과학 교과서’입니다.\n전문가들의 글이다 보니 전문용어가 등장하기도 하고 다소 딱딱하기도 합니다. 하지만 이 시대를 사는 누구나, 특히 미래를 살아가야 할 젊은 세대들이 반드시 갖춰야 할 지식이라고 생각해서 일독을 권합니다."
