        "text": "잡초학을 전공하는 일본의 유명한 식물학자가 쓴 과학에세이입니다.\n“누구에게나 자신에게 빛나는 자리가 있다.”\n“평균에서 벗어나도 좋다! 중심이 될 필요도 없다! 나답게 사는 것이 정답이다.”\n“풀은 가지가지 저마다 공덕 깊은 꽃이구나.”\n개성과 다양성의 소중함을 가르쳐주는 가슴 따뜻한 책입니다.\n저자는 개성과 다양성이 진화를 이끌어갔다는 사실을 설명하면서, 평균과 보통을 강요하는 사회 속에서 개성을 잃지 않는 아웃사이더로 산다는 것의 의미를 강조하고 있습니다.\n2019년부터 3년간 일본 중학교 입시에서 출제지문으로 가장 많이 인용된 책이라고 합니다.\n세상의 아웃사이더들에 대한 힘찬 응원이어서, ‘잘하는 것도 없다. 내가 무엇을 좋아하는지도 모르겠다’며 방황하기 쉬운 청소년들에게 특히 추천하고 싶습니다.\n학부모나 경쟁사회에 지친 성인들이 읽어도 좋은 책입니다.\n식물에 관심있는 사람이라면 적잖은 재미도 맛볼 수 있습니다."
