        "text": "우리 아이들을 이렇게만 키울 수 있다면 얼마나 좋으랴는 생각이 드는 책입니다. 각자의 영역에서 이렇게 선한 의지로 애쓰는 분들이 있어서 세상은 살만하다는 희망을 주는 책입니다. 전남 구례의 용방초등학교는 운동장 너머로 지리산 노고단이 보이고, 울타리를 따라 섬진강 지류 서시천이 흐르는 아름다운 학교입니다. 10년 전만 해도 전교생 17명으로 폐교 위기에 몰렸으나, 이후 혁신학교로 운영되면서 유치원생 포함 전교생 70명으로 되살아나 혁신학교의 성공사례가 됐습니다. 이 책은 저자가 4년 임기의 공모제 교장이 되어 ‘짱구쌤’이란 애칭으로 불리면서, 아이들과 함께 학교를 세상에서 가장 안전하고 행복한 곳으로 만들어 나가는 진짜 선생님의 이야기입니다.\n지난 1월 유튜브에서 <20년 전 약속.. 다들 기억할까?>라는 영상이 조회수 53만을 기록하며 화제가 됐습니다.\n20년 전 전남 시골 초등학교 졸업식날 담임선생님과 제자들이 20년 후 새해 첫날 모교 운동장에서 다시 만나자고 약속했는데, 올해 첫날 그 약속을 잊지 않고 17명의 제자들이 전국 각지에서 모였다는 동화 같은 이야기였습니다.\n그 동화의 주인공인 저자는 참 행복한 사람입니다.\n교육 현장에서 고생하시는 모든 선생님들을 응원하는 마음으로 이 책을 추천합니다.\n이 책은 출판사 역시 전남 구례의 작은 출판사입니다.\n고군분투하는 지역 출판사들에게도 큰 응원을 보냅니다."
