        "recommender": "문재인",
        "text": "시그프리드 헤커 박사의 <핵의 변곡점>은 북핵의 실체와 이를 억제하기 위해 기울였던 외교적 노력이 실패를 거듭해온 이유를 알고 싶다면 반드시 읽어봐야 할 필독서입니다.\n헤커 박사는 미국 핵무기의 산실 로스앨러모스 연구소에서 12년간 소장으로 재직했고, 2004년부터 2010년까지 매년 북한을 방문하여 영변 핵시설과 핵물질을 직접 확인했으며, 미국 역대정부와 의회에 자문역할을 해온 최고의 북핵 권위자입니다.\n이 책은 북한의 핵개발 초기부터 지금에 이르기까지 핵이 고도화되는 과정을 살펴보면서, 외교를 통해 북핵문제를 해결하거나 적어도 억제할 수 있었던 결정적인 변곡점마다 비용과 편익을 분석하는 합리적인 선택이 아니라 과도하게 이념적인 정치적 결정 때문에 번번이 기회를 놓치고 상황을 악화시켜왔다는 사실을 실증적으로 보여줍니다.\n또한 대화 반대자들의 주장과 달리 외교와 대화가 북한에게 핵을 고도화할 시간을 벌어준 것이 아니라, 합의 파기와 대화 중단이 북한에게 시간을 벌어주고 핵발전을 촉진시켜왔다는 사실을 실증적으로 보여줍니다.\n우리에게 뼈아팠던 하노이 북미정상회담의 실패 이유에 대해서도 지금까지의 짐작을 넘어 보다 자세하고 정확한 이유를 알 수 있게 되었습니다.\n전문적이고 두꺼운 책이지만, 북핵에 대한 정확한 정보에 접근할 수 없었던 우리 국민들에게 상세한 정보와 함께 비핵화의 방안에 대한 통찰을 제공해 주는 매우 귀한 책이어서, 관심 있는 이들에게 일독을 권하고 싶습니다."
