        "recommender": "문재인",
        "text": "한미일 삼각동맹은 경제적 측면에서 우리에게 득인가, 아니면 실이 큰가?\n<일본이 온다>는 서울대 국제대학원장이며 최고의 일본경제 전문가인 김현철 교수가 한일 양국 경제를 역사적으로 비교하면서, 한미일 삼각동맹의 경제적 득실을 분석한 책입니다.\n올해 우리 경제는 1%대의 성장률에 그치면서 일본의 경제성장률에 뒤질 것으로 전망됩니다.\n1%대 성장률은 위기 시기의 예외를 제외하고 사상 최초이며, 일본보다 경제성장률이 뒤지는 것도 IMF 위기 때 외에는 처음 있는 충격적인 일입니다.\n지난 정부에서 우리의 1인당 실질국민소득이 일본을 추월했고, 명목국민소득도 추월을 앞두고 있었는데, 격차가 거꾸로 더 벌어지게 되었습니다.\n더욱 우려스러운 것은 우리 경제의 잠재성장률이 사상 최초로 1%대로 떨어졌고, 올해 실제 경제성장률이 그보다도 못할 것이란 전망입니다.\n선진국들의 일반적인 경제성장률이 2%대인데, 우리의 성장률이 그보다 더 떨어져 1%대로 고착되는 것이 아닐까라는 우려입니다.\n한마디로 올해 한일 양국의 경제상황은 ‘일본의 부상, 한국 경제의 위기’라고 말할 수 있습니다.\n이 책은 경제를 발목 잡는 우리 정치와 외교전략이 그 원인임을 밝히고 있습니다.\n글이 쉬운데다 대통령 경제보좌관의 경험이 재미를 더하여 경제서적이지만 술술 읽을 수 있는 책입니다."
