        "recommender": "문재인",
        "text": "<일하며 공부하며, 공부하며 일하며>는 통도사 방장이며, 조계종 종정이신 성파스님의 삶과 예술과 공부 이야기입니다.\n스님은 일반인이 이해하기 힘든 선문답 같은 깨달음이나 견성(見性)을 말하지 않습니다. 대중의 눈높이에 맞춰 자신의 경험을 들려주면서 일 안에 공부가 있고, 공부 안에 일이 있다고 말합니다.\n스님이 서예, 전통한시, 산수화, 도자기, 야생화, 전통천연염색, 전통옹기와 전통된장, 민화, 옻칠예술 등으로 예술활동의 경지를 넓혀가면서 이룬 놀라운 성취들을 보면, “아니, 저 많은 일들을 한 사람이 했다고?”라는 경탄이 절로 나옵니다.\n스님은 그 비결이 일에 대한 간절함과 성의를 다하는 마음자세에 있다고 말합니다.\n스님과 이웃이 된 덕분에 때때로 뵐 수 있었는데, 스님이 요즘 몰두하는 일은 민화와 옻칠예술입니다.\n첫째는 직접 옻칠민화를 그리면서 민화를 한국화의 중심에 세우려는 노력입니다. 둘째는 건칠작업(옻에 토분을 섞어서 칠하는 예술기법)으로 항아리나 불상을 조성하는 것에서 나아가, 건칠만으로 실물크기 전통한옥건물을 건조하겠다는 대담한 구상입니다.\n80세를 훨씬 넘기신 스님의 말씀을 그대로 옮기자면, “무소유라, 욕심을 내려놓으라, 마음을 비우라, 모두 좋은 말들인데, 나는 그렇게 못하겠어요. 나는 지금도 하고 싶은 일이 너무 많아요. 내가 일을 할 수 있을 때까지는 안해본 일을 계속 시도해보고 싶은 욕심이 있어요. 나는 욕심이 대적(大賊) 이라... 하하하.”\n누구나 스님처럼 살 수는 없을 것입니다.\n그러나 우리도 살아가면서 공부하고, 공부하면서 살아간다는 생각을 하면서 살아갈 수 있습니다. 또한 우리도 마음 속에 선한 욕심 하나는 품으면서 살 수 있지 않을까요?"
