        "text": "<<신의 그릇>>은 일본으로 건너가 다완으로 애용되고\n일본 최고의 국보가 되기도 한 조선사발의 미와 역사,\n사기장들의 장인정신을 그린 역사예술소설로서,\n2023년도 양산시 올해의 책으로 선정되었습니다.\n임진왜란 때 일본은 조선에서 수많은 도자기와 사기장들을\n약탈하고 포로처럼 붙잡아 끌고 갔습니다.\n그들의 활약으로 일본의 도자기산업이 비약적으로 발전하여,\n도자기는 일본의 근대화 과정에서 주력 수출상품이 되고\n일본을 대표하는 브랜드가 되었습니다.\n그 때문에 임진왜란은 도자기 전쟁으로 불리기도 합니다.\n조선사발의 역사에는 일찍부터 수준 높은 도자기를 만들었던\n우리의 자부심과 함께 민족수난의 역사가 담겨 있고,\n사기장들의 장인정신과 함께 장인들을 천시하여\n산업의 근대적 발전을 가로막았던 우리 역사의 교훈이\n담겨 있습니다.\n작가 신한균 사기장은 평산마을에서 신정희요를 운영하고\n있는데, 그가 전통가마에서 구워낸 사발과 다기 그리고\n달항아리는 일본에서도 알아줄 만큼 당대 최고의 수준으로\n평가받고 있습니다.\n그가 조선사발의 미와 역사를 알리고자 <사기장 신한균의\n우리 사발 이야기>를 쓴데 이어 이 소설을 썼는데,\n전문소설가가 아닌데도 소설로서도 매우 재미있습니다."
