        "text": "청와대 5년의 비하인드 스토리\n문재인 정부에서 국정홍보비서관으로 일한 윤재관이 청와대에서의 꼬박 5년, 1,826일의 기억을 세상에 내놓는다. 판문점 도보다리 일정 아이디어를 내서 세상에 이름을 알린 저자 윤재관! 그는 2017년 대선 개표일부터 대통령이 퇴임하는 날까지 청와대 1,826일을 누구보다도 가까운 거리에서 문재인 정부를 지켜봤다. 청와대 사람들의 출퇴근부터 수면 부족에 시달리는 실생활 이야기, 문재인 대통령의 인간적인 매력과 엄격함, 2018년 남북정상회담을 성공시키기 위한 치밀한 물밑 작업, 그리고 세월을 돌려 되돌리고 싶은 후회의 순간까지 현장에 있었던 사람만이 알 수 있는 상황을 생생하게 담아냈다.\n저자 윤재관은 국회의원 무급 인턴으로 시작해 비서, 비서관, 보좌관을 거쳐 중앙당 상근부대변인, 청와대 행정관, 선임행정관, 국정홍보비서관을 역임했다. 문재인 정부 5년 동안 청와대 본관과 여민 1, 2, 3관을 모두 거쳤고, 수많은 동료들과 함께했다. 전임 대통령이 탄핵당하는 초유의 사태로 인수위도 매뉴얼도 없는 상황에서, 산을 만나면 길을 내고 물을 만나면 다리를 놓으며 일했다. 청와대 국정홍보비서관으로서 문재인 정부 정책을 국민에게 전해온 저자 윤재관은 이제 청와대 뒷이야기를 풀어놓는다. 훗날 국정운영의 나침반이 되기를 바라면서 화려한 무대 뒤편 청와대 사람들의 땀내 나는 이야기를 기록한다.\n출처_ 교보문고"
