        "text": "아낌없이 주는 나무들의 목소리\n나무는 한 자리에서 억겁의 시간을 살아갑니다. 비가 오나 눈이 오나 바람이 부나 그 자리를 묵묵히 지키고 서 있으면서 한결같이 인간에게 이로움만 베푸는 존재이지요. 그런 나무들이 어떻게 대화하는지, 무엇을 느끼는지 상상해본 적 있을까요. 나무의 세계는 우리가 상상하는 것보다 훨씬 깊고 신비롭습니다. 이 책엔 나무들이 이웃의 약한 나무에게 양분을 나눠주며 생존을 돕는다는 숲과 나무의 경이로운 비밀이 담겨있습니다.\n'나는 나무의 언어, 나무의 사회생활에서 살아가는 법을 배웠다'고 작가는 말합니다. 나무를 아는 사람만이 나무를 보호할 수 있다고 역설하지요. 환경에 적응하며 숲의 생태계를 건강하게 유지하는 나무들의 함께 살기는 우리에게 어떤 지혜를 건네줄까요?\n<나무수업>은 취임 초 '대통령의 서재' 캠페인 때, 어느 분이 좋아하는 구절에 밑줄 치고 메모까지 붙여서, 대통령이 읽으면 좋겠다며 보내온 책입니다. 나무들이 이웃의 약한 나무에게 양분을 나눠주며 생존을 돕는다는 숲과 나무의 경이로운 비밀이 담겨있습니다. 나무들 사이의 우정과 복지 네트워크, 그리고 우리가 모르는 나무들의 놀라운 비밀. 환경에 적응하며 숲의 생태계를 건강하게 유지하는 나무들의 함께 살기는 인간에게도 많은 지혜를 줍니다. 저자는 나무를 아는 사람만이 나무를 보호할 수 있다고 역설합니다."
