        "text": "섞이지도 않지만 밀어내지도 않는 사람들의 나라\n'나마스테(Namaste)'라는 말엔 어떤 의미가 담겼을까요. \"내 안에 있는 신(神)이 당신 안에 있는 신(神)을 존중합니다.\"라는 뜻이라고 합니다. 나와 당신, 만물에 대한 존중과 배려가 담긴 언어이지요. <지극히 사적인 네팔>은 13년째 한국에 살고 있는 '비정상회담' 수잔 샤키야가 고국을 떠올리며 써 내려간 네팔사람들의 이야기입니다.\n무려 126개 민족으로 이루어진 나라. 문화도 언어도 제각각입니다. 모두가 함께 어우러져 평화롭게 살아갈 수 있는 비결은 '나마스테'라는 인삿말에 담겨있습니다. 군더더기 없이 생생한 에세이를 즐겨보세요. 이 책을 덮을 때쯤 여러분의 눈앞엔 어떤 평화가 펼쳐질까요.\n나마스테라는 인사는 \"내 안에 있는 신이 당신 안에 있는 신을 존중한다\"는 뜻입니다. <지극히 사적인 네팔>은 히말라야의 네팔이 아니라 네팔사람들의 네팔을 알고 싶다면 읽을만한 좋은 책입니다. 자신의 나라를 더 알리려고 <비정상회담>에 이어 책을 쓴 수잔 사키야의 열정을 격려하며 추천합니다."
