        "text": "“눈은 천 개, 발은 만 개, 마음은 한 그릇 물처럼 한곳에서 찰랑이는 시인 김민정”(박연준). 시인을 본업으로 편집자를 주업으로 삼는 김민정의 신작 산문집 『말이나 말지』가 출판사 난다에서 출간되었다. 2012년 1월 1일부터 11월 10일까지 한국일보 ‘길 위의 이야기’ 코너에 열한 달 동안 매일같이 실었던 글 266편을 한데 묶었다. 680자라는 네모난 지면에 맞추어 일요일과 추석 연휴를 빼고 매일 쓰기를 했던 그다. 코너명에 걸맞게 원고를 컴퓨터가 아닌 길 위에서 휴대전화 블랙베리 자판으로 찍어 보내며 성실한 마감을 했다. 길 위에서의 다급한 통화나 펄쩍펄쩍 뛰는 말처럼, “하루가 인생의 다인 것처럼”(315쪽) 순간순간 살아간 기록이다. 마트의 말끔히 깐 도라지가 아니라 흙이 그대로 묻은 시장의 도라지(33쪽) 같은 글이다. 인정머리로는 타고난 힘이 장사였던 김민정. 삶에 있어 ‘인정’과 ‘머리’를 최우선에 두는 걸 순리로 알고는 살았다는데, 그가 680자로 포착해 시시콜콜 펼쳐 보이는 우리네 풍경은 경쾌한 웃음 속 비릿한 비애를 목젖 깊숙이 느끼게 한다."
