        "text": "돈을 배우기 전에 사람을 먼저 배우는 경제 수업\n시장의 언어로 인간의 얼굴을 다시 읽는다\n우리는 매일 생산하고 소비하며, 협력하고 경쟁하는 경제구조 속에서 살고 있다. 그러나 우리의 삶 속에서 ‘경제’라는 말은 이해하기 힘든, 여전히 낯설고 어려운 개념으로 다가온다. 『고전툰 2 - 경제』는 사상가들의 말을 쉽게 정리하여 소개함으로써 이런 익숙한 낯섦을 깨뜨린다. 돈과 시장, 노동과 부의 개념을 어려운 경제 공식이 아닌 인간의 선택과 가치의 문제로 풀어내며, 경제학이란 결국 “사람이 더불어 잘 사는 법”을 연구하는 학문임을 이해할 수 있도록 돕는다.\n경제는 숫자가 아니라 인간 사회의 이야기다. 애덤 스미스는 개인의 이익이 사회의 이익으로 이어지는 ‘보이지 않는 손’의 원리를 발견했고, 마르크스는 노동의 소외와 자본의 모순을 비판했다. 헨리 조지는 토지 불평등을, 베블런은 과시적 소비를, 박제가는 나라의 부강보다 백성의 삶을 먼저 생각했다. 다섯 사상가가 말하는 ‘보이지 않는 손’에서 ‘불평등의 구조’까지, 결국 경제는 인간의 이야기와 다름없음을 보여준다."
