        "recommender": "출판사 서평",
        "text": "윤동주의 시집 《하늘과 바람과 별과 시》에 수록된 작품들은 윤동주의 뿌리 깊은 고향상실 의식과, 어둠으로 나타난 죽음에의 강박관념 및 이 모두를 총괄하는 실존적인 결단의 의지를 잘 드러내고 있다. 특히 작품 전반에 두드러지는 어둠과 밤의 이미지는 당시의 분위기를 반영하듯 절망과 공포, 그리고 비탄 등을 드러내어 그의 현실인식이 비극적 세계관에 자리하고 있음을 시사한다. 이 모든 특징은 서정성에 기반을 두는데, 이는 지금까지 독자들이 윤동주의 작품에 깊은 인상을 받게 하는 가장 큰 특징이 된다. 더불어 윤동주는 기독교 정신과 독립에 대한 열망, 투사가 되지 못한 자괴감과 아이들의 눈높이로 본 세상에 대한 묘사까지도 시에 녹여냈다. 이러한 윤동주의 독립과 민족문화 항샹에 대한 노력은 일본 법정에서 내린 판결문에도 잘 드러나 있다. 일본 법정에서 밝힌 윤동주의 죄명은 다음과 같았다.\n“피고인 윤동주는 조선 독립을 위해 실력을 키우고 조선인의 능력과 민족성을 향상시켜 독립운동의 소질을 배양해야 하며, 일반 대중의 문화 앙양 및 민족의식의 유발에 힘써야 한다고 결의하기에 이르렀다. 대동아전쟁 발발에 직면한 일본의 패배를 꿈꾸며 그 때 조선독립의 야망을 실현시키고 이로 인해 일본이 망한다고 하는 신념을 굳게 하였다. 이에 본 법정은 치안 유지법 제5조에 해당하는 형기 범위 내에서 피고인을 징역 2년에 처하고 형법 제21조 2항에 의거 미결 구류일수 120일을 형에 포함한다.”\n_1944년 3월 31일 교토지방재판소 제2형사부 판결문 중\n이번 더스토리에서 출간하는 《하늘과 바람과 별과 시》는 1955년 정음사 판본의 표지를 그대로 차용했으며, 본문은 시의 의미가 훼손되지 않도록 오리지널 원문을 그대로 살렸다. 또한 윤동주 시인의 친필원고와 재판 판결문 원본을 별책으로 제작해서 민족을 위해 치열한 삶을 살았던 시인 윤동주를 다시 들여다보는 계기를 만들었다.\n윤동주에게 큰 영향을 끼쳤으며 후에 경향신문에 <쉽게 쓰여진 시>를 소개한 시인 정지용은 “윤동주가 살아 있다면, 한국의 시는 더욱 발전했을 것”이라고 극찬했다. 암울한 시대 속에서 끝없는 자아성찰을 통한 시작(詩作)으로 민족의 아픔을 어루만진 윤동주는 시대가 변한 지금도 우리 곁에 남아 또 다른 위로와 격려를 건넨다."
