        "text": "홍범도를 위대한 장군으로 그릴 생각은 조금도 없었다. 나는 홍범도를 통해 한 시대의 가치가 어떻게 새롭게 출현하고, 그 가치가 어떻게 낡은 가치를 돌파하면서 자신의 길을 가는지를 알고 싶었다. _‘작가의 말’에서\n6월 7일, 문학동네가 대한독립군을 이끈 홍범도의 생애와 일제에 맞선 포수들의 항일 무장투쟁을 다룬 장편소설 『범도』를 펴낸다. 6월 7일은 1920년, 3·1운동 이후 대한독립군이 일본군과 처음으로 맞붙은 대규모 전투이자 독립군이 대승을 거둔 ‘봉오동 전투’의 개전일이다. 『범도』는 신동엽문학상, 황순원문학상, 오영수문학상을 수상한 소설가 방현석이 다년간의 취재와 자료 조사를 거쳐 10년이 넘는 시간 동안 집필한 필생의 역작으로, 홍범도가 산짐승을 사냥하는 포수로서 산야를 떠돌다 항일 운동에 투신하여 각종 인간군상을 만나며 성장해나가는 과정을 그린 작품이다. “홍범도를 위대한 장군으로 그릴 생각은 조금도 없었다”라는 작가의 말대로 『범도』에는 영웅 홍범도가 아닌 엄혹한 시대에 웃고 울고 사랑하고 갈망하며 자신만의 신념을 품고 살아간 한 인간의 삶이 담겨 있다. 또한 『범도』는 홍범도 한 사람의 이야기가 아니라 항일 무장투쟁이라는 큰 조류를 함께 만들어나간 수많은 인물들의 이야기이기도 하다. 그 속에는 영웅적인 면모를 보인 사람도, 비겁했던 사람도, 거대한 파도 속에서도 자신만의 삶을 지켜낸 사람도 있다. 그래서 방현석이 펼쳐 보이는 이 이야기는 이 시대를 살아가는 우리의 삶의 모습과도 닮아 있다. 각각의 시대에는 각각의 어려움이 있다. 『범도』가 던지는, ‘삶 속에서 어떤 가치를 수호하며 살아갈 것인가’ 하는 질문은, 그들이 만든 지금의 세상에 살고 있는 우리에게도 여전히 유효하다.\n독립군을 이끈 홍범도가 중앙아시아로 강제 추방당해 카자흐스탄의 한 도시에서 극장 수위로 일하다 생을 마감했다는 사실을 아는 이는 많지 않을 것이다. 해방 2년 전인 1943년 머나먼 타국에서 세상을 떠난 홍범도의 유해는 2021년 8월 15일 우리나라로 봉환되었다. 의병으로 활동하다 일제에 강제 해산을 당한 뒤 연해주와 만주를 떠돌며 군수품을 마련해 이윽고 대한독립군으로서 싸운 홍범도는 또 한번 이국을 떠돌다 마침내 귀환한 셈이다. 그 누구보다 온몸으로 한 시대를 살아낸 홍범도의 파란만장한 여정, 그와 함께 싸운 포수들의 항일 무장투쟁의 대서사시가 『범도』에서 장대하게 펼쳐진다."
