        "recommender": "평산책방 소개",
        "text": "연암을 읽는다는 것은 무엇인가.\n연암 속으로 들어가는 것을 의미한다. 연암 주변을 아무리 빙빙 배회해 봤자 연암의 진면목을 알기는 어렵다. 연암을 알기 위해서는 연암의 마음속으로 들어가지 않으면 안 된다. 연암이 무엇을 괴로워했는지, 무엇을 기뻐했는지, 무엇을 슬퍼했는지, 무엇에 분노했는지, 스스로 연암이 되어 느껴보지 않으면 안 된다. 하지만, 연암을 읽는다는 일이, 단지 연암의 시선으로 삶과 자연과 세상을 읽는 데 그치는 것은 아니다. 그것은 동시에 스스로의 시선, 다시 말해 우리 시대 ‘나’의 시선으로 삶과 자연과 세상을 읽는 일이기도 한 것이다. 그럴 경우, 사유하는 주체이자 심미적 주체로서의 연암은, 또다른 사유의 주체이자 심미적 주체인 ‘나’와 부단히 교섭하면서 대화적 관계를 형성할 수 있다. 이를 통해, ‘나’가 연암 속으로 들어가기만 하는 것이 아니라, 연암이 ‘나’ 속으로 들어오기도 하며, 이 과정을 통해 죽었던 연암은 환생하게 되고, ‘나’는 내가 속한 좁은 시공간을 넘어 자아의 놀라운 확충을 경험하게 된다. 실로 경이로운 일이다.\n「책머리에」 中에서 만일 이 글이 이 마지막 단락 없이 앞 단락에서 끝났다면 어땠을까, 이런 질문을 한번 던져 보자. 만일 이 마지막 단락 없이 글이 끝났다면 이 글은 그야말로 세상에 버려진 존재들이 달밤에 만취하여 하릴없이 어슬렁거리고 다니면서 동류의식과 자기연민을 보여준 데 지나지 않을 것이다. 그것도 나쁘지는 않지만, 연암은 거기서 글을 종결짓지 않고 자신들이 그런 존재조건에 있음에도 불구하고(아니 오히려 그런 존재조건에 있기 때문에 더욱 더 진실하게) 선비로서의 정신을 결코 놓고 있지 않음을 보여주는 대목을 살짝 끝에 덧붙임으로써 이 글에 기복(起伏)과 파란(波瀾)을 부여하고 있다. 그 결과 이 글은 대단히 성찰적이고 반어적인 울림을 획득한다. 왜 성찰적이고 반어적인가? 스스로의 존재조건을 응시해 내고 있다는 점, 자기연민의 감정까지도 대상화하고 반추해 내는 고도의 냉철한 지적 능력을 보여준다는 점, 이상한 기행(奇行)을 연출하면서도 그 기행이 하릴없는 데서 연유하는 것임을 스스로 꿰뚫어보면서 기행 저 너머에 있는 선비 본연의 사회적 책무를 스스로 환기해 내고 있다는 점, 이 여러 가지 점에서 그렇다고 말할 수 있다. 이처럼 ‘성찰성’과 ‘반어성’은 연암 산문의 기저부(基底部)를 이루는바, 이 점을 알지 못하는 자, 연암 산문의 껍데기만 읽은 자라 할 것이다. ― 본문 84∼85p"
