        "text": "사랑하는 한국의 어린이와 독자 여러분께\n잠잠할 때도 있고 터질 것처럼 쿵쾅거릴 때도 있습니다. 왼쪽 가슴에 손을 대어 보세요. 느껴지나요? 바로 심장입니다.\n심장은 우리 몸속 깊이 자리한 아주 튼튼한 근육입니다. 놀랍게 생긴 심방과 심실, 판막으로 이루어져 있지요. 심장은 하루에 십만 번을 뜁니다. 피를 온몸으로 실어 날라 우리가 살아갈 수 있게 해 주지요. 심장은 낮에도 밤에도, 우리가 잠잘 때에도 일을 합니다. 게다가 우리는 사랑 없이 살 수 없기 때문에 사랑에 관한 일도 맡아 합니다. 우리는 오로지 심장을 통해 사랑을 느낄 수 있고 사랑을 베풀 수 있습니다. 사랑은 우리 삶에서 가장 중요한 것이죠. 하지만 심장에서 우러나지 않은 사랑은 우리를 충만하게 하는, 세상에서 가장 아름다운 감정이 될 수 없습니다. 그저 생각에 불과할 뿐이지요.\n어떻게 그리 잘 아냐고요? 평생 동안 내 손으로 수많은 심장을 만져 왔기 때문입니다. 아주 작은 아기의 심장부터 무척 나이 든 노인의 심장까지 다양한 심장들을 만져 왔지요. 심장이 아플 때 심장을 고쳐 주는 사람, 심장외과 의사니까요.\n오늘날 우리는 심장에 관해 내가 학생이었을 때보다 훨씬 많은 것을 알고 있습니다. 심장은 감각 기관이며 뇌에 많은 것들을 알려 줍니다. 과학자들은 심장과 뇌 사이의 비밀스러운 연결고리들을 발견해 내고 있습니다. 심장과 뇌, 이 둘은 흔히 말하듯 경쟁자가 아닙니다. 오히려 최고의 친구입니다. 둘은 신경 체계, 맥박, 전자장과 호르몬을 통해 흥미진진한 메시지를 끊임없이 주고받습니다.\n심장을 건강하게 유지하고 크고 강인하게 만들려면, 심장의 목소리에 귀 기울이는 일이 무척 중요합니다. 심장의 목소리는 지혜로워서 삶에서 정말 중요한 게 무엇인지를 말해 줍니다. 심장에서 우러나는 기쁨과 감사가 특히 중요하지요. 여러분은 오늘 아름다운 일을 경험했나요? 뭔가 설레는 것을 보았나요? 감사하고 싶은 일은 무엇인가요? 우리를 행복하고 감사하게 만드는 것들은 아주 단순하고 작은 것일 때가 많습니다.\n지금 나는 여러분에게 감사를 전하고 싶습니다! 나의 책을 읽어 주셔서 고맙습니다.\n우리 모두는 심장과 심장으로 연결됩니다.\n- 라인하르트 프리들"
