        "text": "미국-중국 경쟁, 북한 핵무장 강화에 우크라이나 전쟁까지, 변하지 않는 지정학적 운명은 또다시 한반도와 동북아의 평화에 물음표를 가져왔다. 미중경쟁은 경제와 기술 분야를 넘어 체제와 문화 부문으로 심화되었고, 2023년 들어 외신과 국제정치 전문가들은 중국의 대만 침공과 제3차 세계대전까지 운운한다. 대한민국은 ‘실존적 위기’에 직면했지만 2023년의 외교는 국민의 확실한 믿음을 얻지 못하고 있다.\n이에 이낙연 전 총리가 침묵을 깨고 국제사회에서의 한국의 역할을 점검하고 그 방향을 제시한다. 이 전 총리는 일본 특파원을 지낸 기자 시절부터 ‘일본통’으로 통했고, 국무총리 시절 대통령과의 ‘투톱 외교’로 총리로서는 전례 없이 많은 30개국을 방문했다. 그가 지난 1년간은 워싱턴DC에 머무르며 미중경쟁 및 한반도 평화를 주제로 연구했고, 그 결실을 책으로 내놓는다. 이 전 총리는 조지워싱턴대 방문연구원으로 체류하며 문헌을 검토함은 물론, 주요 인사를 만나고 워싱턴DC의 싱크탱크 세미나에 참석했다. 통일외교 정책에 대해 총체적으로 공부하고 구상하는 중요한 시간이었다.\n《대한민국 생존전략》은 격화된 미중경쟁과 한반도를 둘러싼 4강국(미, 중, 일, 러) 사이에서 대한민국에 달라진 외교 정책과 함께 용기와 지혜를 주문한다. 지정학적 상황을 충분히 숙지하고, 정세와 명분을 고려하며, 이익을 따지면서도 분단국가로서의 역사와 당위를 고민한다. 특파원, 국회의원, 총리를 거치며 겪은 당사자로서의 경험을 녹여내었음은 물론이다. 더불어 이 전 총리가 출간을 전후해 연초부터 미국과 독일 소재 대학에서 직접 여덟 번의 강연을 진행하고 있기에 해당 원고를 부록으로 싣는다."
